  const hx = 0, hy = rb - 62;
  // plume
  c.beginPath(); c.moveTo(-5, hy - 16); c.quadraticCurveTo(-6, hy - 34, 4, hy - 36); c.quadraticCurveTo(12, hy - 30, 6, hy - 16); c.closePath(); g.fill(tm.main);
  // helm
