    c.save(); c.translate(tip[0], tip[1]); c.rotate(Math.atan2(tip[1] - b[1], tip[0] - b[0])); c.beginPath(); c.moveTo(-1, -2.8); c.lineTo(10, 0); c.lineTo(-1, 2.8); c.closePath(); g.fill(PAL.steelL); c.restore();
