    const ring = [[-44, -16.5], [42, -16.5], [42, 16.5], [-44, 16.5], [-44, -16.5]];
    crew(S, [[-8, -12, 19], [8, -12, 19], [22, 11, 19], [-20, 12, 19], [30, -11, 19]], 'korea');
    wall(S, ring, 19, 5, WD.hullD, { crenel: 4, crenelH: 3, trim: S.team.main });
    // commander's pavilion
