    c.lineTo(12, -8); c.quadraticCurveTo(30, -6, 40, 4); c.quadraticCurveTo(46, 12, 40, 18);
    c.lineTo(-18, 18); c.quadraticCurveTo(-22, 10, -18, 0); c.closePath();
