    gg.addColorStop(0, `rgba(${rgb},0.95)`); gg.addColorStop(0.16, `rgba(${rgb},0.5)`); gg.addColorStop(1, `rgba(${rgb},0)`); c.fillStyle = gg; c.fillRect(x, y, w, h);
    // slow rays fanning from the sun
