  win(-21, -80, 7, 26); win(-5, -80, 7, 26);
  for (const px of [-30, -2]) { c.beginPath(); c.moveTo(px - 2, -122); c.lineTo(px + 2, -142); c.lineTo(px + 6, -122); c.closePath(); c.fillStyle = st; c.fill(); ink(c, 1.8); }
