  c.beginPath(); c.moveTo(-24, 0); c.lineTo(22, 0); c.lineTo(20, -8); c.lineTo(-22, -8); c.closePath(); c.fillStyle = PAL.wood; c.fill(); ink(c, 2);
  c.save(); c.translate(recoil, 0);
