      c.beginPath(); c.moveTo(gx + 2.4, gy - half - 1); c.quadraticCurveTo(gx - 3, gy, gx + 2.4, gy + half + 1); c.lineTo(gx + 5.6, gy + half + 1); c.quadraticCurveTo(gx + 1.5, gy, gx + 5.6, gy - half - 1); c.closePath(); g.fill(wood);
