  const aiming = p.stage === 'aim' || p.stage === 'fire' || p.stage === 'smoke';
  sArm(g, -3, shoY + 3, aiming ? fh[0] : bh[0] + 2, aiming ? fh[1] : bh[1], shade(sleeve, -0.3), shade(sk, -0.2), aiming ? 1 : -1);
