defFoot('afghanSword', 'Swordsman', 'sword', { skin: SKIN.afghan, head: { kind: 'afghan', col: '#f1e9d6' }, legs: '#e7dcc2', feet: '#7a4a26', weapon: 'talwar', shield: 'dhal', shieldCol: '#3a2a22', torso: 'robe', sash: '#4a6a8a', hem: -12, beard: '#2a1d16' });
