  const box = () => { c.beginPath(); c.moveTo(-w, base); c.lineTo(-w - 2, base - H); c.lineTo(w + 2, base - H); c.lineTo(w, base); c.closePath(); };
  box(); g.fill(royal ? PAL.gold : ELE.wood);
