  const c = g.c, sk = M.skin || SKIN.in;
  if (part === 'leg') { c.beginPath(); cap(c, x, y - 3, x + 9, y + 9, 9); cap(c, x + 9, y + 9, x + 5, y + 24, 8); g.fill(M.cloth || DHOTI); return; }
