  const tp = () => { c.beginPath(); c.moveTo(x - 10, sh); c.quadraticCurveTo(x + 2, sh - 4, x + 10, sh + 1); c.quadraticCurveTo(x + 13, sh + 14, x + 10, y + 2); c.quadraticCurveTo(x, y + 5, x - 11, y + 1); c.quadraticCurveTo(x - 13, sh + 14, x - 10, sh); c.closePath(); };
