GAME.nation = (k) => GAME.NATIONS[k] || GAME.NATIONS.default;
GAME.artOf = (nat, role) => GAME.nation(nat).art[role] || role;
GAME.roleName = (nat, role) => GAME.nation(nat).names[role] || (RTW.TROOPS[role] ? RTW.TROOPS[role].name : role);
GAME.cardTitle = (id, nat) => { const o = GAME.nation(nat).cards[id]; return o ? o[0] : GAME.CARDS[id].title; };
GAME.cardShort = (id, nat) => { const o = GAME.nation(nat).cards[id]; return o ? o[1] : GAME.CARDS[id].short; };

