/* ===== src/game/64b-decor3.js ===== */
/* Roll to War: battlefields of the Indian campaigns (merged into BATTLE_DECOR by 65-battle.js). ground() paints
   into the cached field (field coordinates, 390 x 572); anim() draws every frame in screen coordinates. */
const plainBase = (g, Wd, H, seed, key = 'dry') => { g.fillStyle = W.grassPattern(g, 1, key); g.fillRect(0, 0, Wd, H); W.wornGround(g, Wd / 2, H * 0.5, Wd * 0.44, H * 0.28, seed); };
// a small Indian town: flat-roofed mud-brick houses, with a temple tower (or a mosque dome) among them
function inTown(g, cx, by, w, seed, o = {}) {
  const R = rng(seed), n = Math.max(4, Math.round(w / 24));
  if (o.temple) PROP[o.temple](g, cx - w / 2 + w * (o.at != null ? o.at : 0.3), by - 6, o.ts || 0.45, 0, { col: o.tcol });
  if (o.dome) PROP.dome(g, cx - w / 2 + w * o.dome, by - 4, 0.55, 0);
  const cols = o.cols || ['#dcc08e', '#cfae7c', '#e2cc9e'];
  for (let i = 0; i < n; i++) { const hx = cx - w / 2 + (i + 0.5) * (w / n) + (R() - 0.5) * 4; PROP.house(g, hx, by - (i % 2) * 3, 1, 0, { w: w / n + 4, h: 14 + R() * 10, style: 'flat', col: cols[(R() * cols.length) | 0], door: R() < 0.6 }); }
}
const campRow = (g, list, s = 0.55, kind = 'tent') => list.forEach(([x, y, col]) => PROP[kind](g, x, y, s, 0, { col }));
const dryTrees = (g, list, r = 14) => { for (const [x, y] of list) W.tree(g, x, y, r, Math.round(x * 3 + y), 'dry'); };
const palms = (g, list) => { for (const [x, y, s] of list) RTW.palm(g, x, y, s || 0.8, 0, Math.round(x + y * 3)); };
// a band of water across the top of the field with a sandy bank below it
function topRiver(g, Wd, y, col = '#4f8fb0') {
  g.fillStyle = '#e6d3a4'; g.beginPath(); g.moveTo(0, 0); g.lineTo(Wd, 0); g.lineTo(Wd, y + 10); g.bezierCurveTo(Wd * 0.7, y + 18, Wd * 0.3, y + 2, 0, y + 12); g.closePath(); g.fill();
  const wg = g.createLinearGradient(0, 0, 0, y); wg.addColorStop(0, shade(col, -0.15)); wg.addColorStop(1, col); g.fillStyle = wg;
  g.beginPath(); g.moveTo(0, 0); g.lineTo(Wd, 0); g.lineTo(Wd, y); g.bezierCurveTo(Wd * 0.7, y + 8, Wd * 0.3, y - 8, 0, y + 2); g.closePath(); g.fill();
  g.strokeStyle = 'rgba(255,255,255,0.4)'; g.lineWidth = 1.2; for (let i = 0; i < 9; i++) { const x = 10 + i * 44, yy = 8 + (i % 3) * ((y - 14) / 3); g.beginPath(); g.moveTo(x, yy); g.quadraticCurveTo(x + 7, yy - 3, x + 14, yy); g.stroke(); }
}
