/* ===== src/game/65-battle.js ===== */
/* Roll to War: the battle scene */
const BTOP = 96, BBOT = 668;
// bottom bar: bonus choices (a new offer every 8-10 s) above a compact survivor strip
const MC = { w: 116, h: 74, y: 694 };
const mcX = (i) => 8 + i * (MC.w + (GAME.app.W - 16 - MC.w * 3) / 2);
const STRIP = { x: 8, y: 776, w: 374, h: 62 };
const STAT_STYLE = {
  atk: { color: PAL.attack, valueCol: PAL.attackD, badge: 'fist' },
  def: { color: PAL.armor, valueCol: PAL.armorD, badge: 'shield' },
  range: { color: PAL.speed, valueCol: '#9a6a10', badge: 'range' },
  rate: { color: PAL.move, valueCol: PAL.moveD, badge: 'rate' },
  heal: { color: '#e0607a', valueCol: '#a8263f', badge: 'heal' },
};
const FX_RING = { atk: '#ff6a55', def: '#58a6ff', rate: '#5fd98a', range: '#ffd24a', heal: '#ff8fb0' };
const ATK_POSE = { piker: 0.42, crossbow: 0.28, knight: 0.45, sword: 0.48 };
const HERO_SIZE = 32;   // heroes and commanders are drawn bigger than their troops
// arrows (not crossbow bolts): the height of their arc, [most, share of the distance]
const BOW_ARC = { longbow: [60, 0.3], horseArcher: [34, 0.2], turkArcher: [34, 0.2], inArcher: [44, 0.24], cholaArcher: [44, 0.24], southArcher: [44, 0.24], afghanArcher: [44, 0.24] };

function cardData(id) {
  const cd = GAME.CARDS[id], st = STAT_STYLE[cd.stat];
  const o = { title: cd.title, value: GAME.cardValueText(id), desc: cd.desc, color: st.color, valueCol: st.valueCol, seed: id.length * 3 + 1 };
  if (cd.type) { o.troop = cd.type; o.anim = 'attack'; o.animT = ATK_POSE[cd.type] * GAME.UT[cd.type].anim; o.badge = st.badge === 'rate' || st.badge === 'heal' ? null : st.badge; o.extraBadge = st.badge === 'rate' ? 'rate' : null; }
  else if (cd.stat === 'def') o.icon = 'shield';
  else if (cd.stat === 'atk') o.icon = 'fist';
  else o.customIcon = cd.stat;
  if (cd.stat === 'heal') o.desc = 'Heals every survivor\n' + o.value + ' of full health';
  return o;
}
// compact bonus card for the bottom bar: colour band with the troop or icon and the value, then name and effect
function drawMiniCard(g, x, y, id, nat) {
  const w = MC.w, h = MC.h, cd = GAME.CARDS[id], st = STAT_STYLE[cd.stat], seed = id.length * 3 + 1;
  g.fillStyle = 'rgba(10,6,3,0.45)'; g.beginPath(); rr(g, x + 1, y + 4, w, h, 10); g.fill();
  g.beginPath(); rr(g, x, y, w, h, 10); g.lineWidth = 3; g.strokeStyle = INK; g.stroke();
  const fg = g.createLinearGradient(0, y, 0, y + h); fg.addColorStop(0, PAL.goldL); fg.addColorStop(1, PAL.goldD); g.fillStyle = fg; g.fill();
  UI.parch(g, x + 4, y + 4, w - 8, h - 8, 7, { shadow: false, seed });
  const bx = x + 7, by = y + 7, bw = w - 14, bh = 31;
  g.save(); g.beginPath(); rr(g, bx, by, bw, bh, 6); g.clip();
  const bg = g.createLinearGradient(0, by, 0, by + bh); bg.addColorStop(0, shade(st.color, 0.3)); bg.addColorStop(1, shade(st.color, -0.32)); g.fillStyle = bg; g.fillRect(bx, by, bw, bh);
  g.globalAlpha = 0.18; g.fillStyle = '#fff';
  for (let i = 0; i < 6; i++) { const a = -Math.PI / 2 + (i - 2.5) * 0.4; g.beginPath(); g.moveTo(bx + 20, by + bh); g.lineTo(bx + 20 + Math.cos(a - 0.08) * 90, by + bh + Math.sin(a - 0.08) * 90); g.lineTo(bx + 20 + Math.cos(a + 0.08) * 90, by + bh + Math.sin(a + 0.08) * 90); g.closePath(); g.fill(); }
  g.globalAlpha = 1;
  if (cd.type) { UI.bust(g, bx + 3, by + 3, bh - 6, bh - 6, GAME.artOf(nat, cd.type), 'blue', 0, { r: 5 }); g.beginPath(); rr(g, bx + 3, by + 3, bh - 6, bh - 6, 5); g.lineWidth = 1.6; g.strokeStyle = INK; g.stroke(); }
  else {
    const cx = bx + bh / 2 + 2, cy = by + bh / 2;
    if (cd.stat === 'def') ICON.shield(g, cx, cy, 22, PAL.armor);
    else if (cd.stat === 'atk') ICON.fist(g, cx, cy + 1, 21);
    else if (cd.stat === 'rate') ICON.chevrons(g, cx - 1, cy, 9, 3, '#eafff0');
    else { g.beginPath(); circ(g, cx, cy, 11); g.lineWidth = 2.5; g.strokeStyle = INK; g.stroke(); g.fillStyle = '#fffaf0'; g.fill(); g.fillStyle = '#e0445e'; g.fillRect(cx - 2.5, cy - 7, 5, 14); g.fillRect(cx - 7, cy - 2.5, 14, 5); }
  }
  g.restore();
  g.beginPath(); rr(g, bx, by, bw, bh, 6); g.lineWidth = 1.8; g.strokeStyle = INK; g.stroke();
  RTW.text(g, GAME.cardValueText(id), bx + bw - 6, by + bh / 2 + 1, { size: 17, weight: 700, fill: '#fff', stroke: INK, strokeW: 3.5, align: 'right' });
  RTW.text(g, GAME.cardTitle(id, nat), x + w / 2, y + 49, { size: 10.5, font: F.head, weight: 900, fill: INK, maxW: w - 14 });
  RTW.text(g, GAME.cardShort(id, nat), x + w / 2, y + 63, { size: 9.5, weight: 600, fill: '#5a4127', maxW: w - 14 });
}
// "Piker Fury ×3 · Shield Wall ×2 · +4 more"
function picksSummary(ids, max = 2, nat) {
  if (!ids.length) return '—';
  const n = {}; for (const id of ids) n[id] = (n[id] || 0) + 1;
  const keys = Object.keys(n).sort((a, b) => n[b] - n[a]);
  const name = (id) => GAME.cardTitle(id, nat).split(' ').map((w) => (w[0] === "'" ? w : w[0] + w.slice(1).toLowerCase())).join(' ');
  let out = keys.slice(0, max).map((id) => name(id) + (n[id] > 1 ? ' ×' + n[id] : '')).join(' · ');
  const rest = keys.slice(max).reduce((a, id) => a + n[id], 0);
  if (rest) out += ` · +${rest} more`;
  return out;
}

function battleGround(g, Wd, H, seed, decor) {
  const D = decor && BATTLE_DECOR[decor], R = rng(seed), night = !!(D && D.night);
  if (D && D.base) D.base(g, Wd, H);
  else {
    g.fillStyle = W.grassPattern(g, 1); g.fillRect(0, 0, Wd, H);
    // trodden earth where the armies meet
    W.wornGround(g, Wd / 2, H * 0.5, Wd * 0.46, H * 0.3, seed);
  }
  // sunlight from the upper left and cool shade to the lower right, before the props
  if (!night) W.lightWash(g, 0, 0, Wd, H, { vig: 0, sun: D && D.sea ? 0.7 : 1, shade: 0.8 });
  // wild flowers and tufts along the edges, clear of the fighting
  if (!(D && D.dry)) {
    for (let i = 0; i < 12; i++) {
      const side = i % 2 ? 1 : -1, x = side < 0 ? 8 + R() * 60 : Wd - 8 - R() * 60, y = 30 + R() * (H - 60);
      W.flowerPatch(g, x, y, 5 + R() * 5, seed * 7 + i, ['daisy', 'butter', 'daisy', 'pink', 'violet'][i % 5]);
    }
  }
  if (D && D.ground) D.ground(g, Wd, H, R);
  else {
    for (let i = 0; i < 6; i++) W.rock(g, R() < 0.5 ? 4 + R() * 10 : Wd - 4 - R() * 10, 40 + R() * (H - 80), 3 + R() * 4, i + seed);
    for (let i = 0; i < 5; i++) W.bush(g, i % 2 ? Wd - 6 - R() * 10 : 6 + R() * 10, 90 + i * 90 + R() * 30, 7 + R() * 3, i + seed);
    // tree line peeking under the top bar
    for (let i = 0; i < 10; i++) W.tree(g, -8 + i * 44 + (i % 2) * 10, 8 + (i % 2) * 5, 15 + (i % 3) * 2.5, i + 50 + seed, i % 2 ? -0.06 : 0);
  }
  // a soft vignette pulls the eye to the middle of the field
  W.lightWash(g, 0, 0, Wd, H, { sun: 0, shade: 0, vig: night ? 0.5 : D && D.sea ? 0.55 : 0.75, vigCol: D && D.sea ? '8,30,56' : D && D.dry ? '70,40,10' : '14,34,8' });
}
