      if (u.fxT > 0 && u.fxKind) { const col = FX_RING[u.fxKind] || '#fff'; c.save(); c.globalAlpha = Math.min(1, u.fxT * 1.4); c.beginPath(); ell(c, u.x, u.y, 12 - u.fxT * 3, 5); c.lineWidth = 2.5; c.strokeStyle = col; c.stroke(); c.restore(); }
      if (u.leader) heroRing(c, u.x, u.y, 22, u.team, this.t);
      if (u.state === 'attack') { const iv = u.iv / (sim.mods[u.team].rate[u.type] * (u.fR || 1)); s = SPR.btroop(a, u.team, view, 'attack', Math.floor(clamp(Math.max(0, u.atk) / iv, 0, 0.999) * 6), sz); }
      else if (u.hitT < 0.09) s = SPR.btroop(a, u.team, view, 'hit', 0, sz);
