    if (S.pegs) { const P = S.pegs; for (let i = 0, n = Math.max(3, Math.round((P.x1 - P.x0) / 9)); i < n; i++) stake(c, lerp(P.x0, P.x1, i / (n - 1)), P.y + (i % 2) * 3, (i % 2 ? 0.35 : -0.35) + Math.PI, 0.55); }
