        RTW.text(c, f.str, clamp(f.x, 60, GAME.app.W - 60), f.y - easeOut(k) * (f.small ? 22 : 40), { size: f.small ? 11 : 15, font: F.head, weight: 900, fill: f.col, stroke: INK, strokeW: f.small ? 3 : 4, maxW: GAME.app.W - 30 });
        c.restore();
