        const u = f.u, s = easeOutBack(clamp(k / 0.18));
        c.save(); c.globalAlpha = k < 0.8 ? 1 : 1 - (k - 0.8) / 0.2;
        const x = clamp(u.x, 80, GAME.app.W - 80), y = Math.max(BTOP + 30, u.y - 74);
