    const on = GAME.settings.music;
    const b4 = A.hit('bmusic', 75, 494, W2 - 150, 40, () => { GAME.settings.music = !GAME.settings.music; GAME.saveSettings(); GAME.sfx.apply(); GAME.sfx.tap(); });
    UI.button(c, 75, 494 + (b4 ? 2 : 0), W2 - 150, 40, on ? 'MUSIC  ON' : 'MUSIC  OFF', on ? 'green' : 'wood', { size: 14 });
