  c.fillStyle = g; c.fillRect(0, 0, Wd, Ht);
  if (dry) RTW.dryGround(c, 0, Ht * 0.46, Wd, Ht * 0.54, 'sand', 77);
  else { c.fillStyle = W.grassPattern(c, 1); c.fillRect(0, Ht * 0.46, Wd, Ht * 0.54); }
  if (!win) { c.fillStyle = 'rgba(40,20,50,0.28)'; c.fillRect(0, 0, Wd, Ht); }
  c.fillStyle = dry ? (win ? '#d2ae78' : '#a8885e') : win ? '#7fae6a' : '#5f7d57'; c.beginPath(); c.moveTo(0, Ht * 0.47); c.quadraticCurveTo(Wd * 0.3, Ht * 0.39, Wd * 0.6, Ht * 0.45); c.quadraticCurveTo(Wd * 0.85, Ht * 0.5, Wd, Ht * 0.43); c.lineTo(Wd, Ht * 0.5); c.lineTo(0, Ht * 0.5); c.closePath(); c.fill();
