    SPR.blit(c, SPR.image(this.groundKey, A.W, BBOT - BTOP, (g) => battleGround(g, A.W, BBOT - BTOP, 7 + this.li * 5, this.decor)), 0, BTOP);
    if (D && D.seaAnim) { c.save(); c.translate(0, BTOP); D.seaAnim(c, t, sim); c.restore(); }
    if (!(D && D.night)) AMB.glints(c, 0, BTOP, A.W, BBOT - BTOP, t, 18, this.li + 3);
    // sinking ships lie under everything afloat
    const afloat = [];
    for (const u of sim.units) { if (!u.alive && !u.leaving) { if (u.deadT < 3.4) this.drawShipUnit(c, u); } else afloat.push(u); }
    for (const u of afloat) if (u.moving && (u.fade == null || u.fade > 0.6)) this.drawWake(c, u);
    afloat.sort((a, b) => a.y - b.y);
