      const tx = b.tx, ty = b.ty - 8, dist = Math.hypot(tx - b.x0, ty - b.y0);
      const arc = b.art === 'fire' ? Math.min(44, dist * 0.26) : b.art === 'ball' ? Math.min(22, dist * 0.12) : Math.min(6, dist * 0.04);
      const x = lerp(b.x0, tx, k), y = lerp(b.y0, ty, k) - Math.sin(Math.PI * k) * arc;
      if (b.art === 'fire') RTW.fireArrow(c, x, y, Math.atan2(ty - b.y0 - Math.cos(Math.PI * k) * arc * Math.PI, tx - b.x0));
      else if (b.art === 'ball') RTW.cannonball(c, x, y);
