      c.fillStyle = 'rgba(6,12,34,0.4)'; c.fillRect(0, BTOP, A.W, BBOT - BTOP);
      const glow = SPR.image('nglow', 64, 64, (g) => { const rg = g.createRadialGradient(32, 32, 1, 32, 32, 31); rg.addColorStop(0, 'rgba(255,170,80,0.55)'); rg.addColorStop(1, 'rgba(255,140,60,0)'); g.fillStyle = rg; g.fillRect(0, 0, 64, 64); });
