      c.globalAlpha = 0.45;
      for (const u of afloat) { if (ng >= 16) break; const hp = u.alive ? u.hp / u.maxHp : 1; if (hp < 0.3 && !u.leader && (u.id % 3 === 0)) { const r = 16 + (0.3 - hp) * 30; c.drawImage(glow.cv, u.x - r, u.y - r - 8, r * 2, r * 2); ng++; } }
      c.globalAlpha = 0.5; let nm = 0;
      for (const f of this.fx) if (f.kind === 'muzzle' && t - f.t0 < 0.2 && nm++ < 14) c.drawImage(glow.cv, f.x - 18, f.y - 18, 36, 36);
      c.globalAlpha = 1;
