    if (u.leader === 'yisunsin' && this.sim.twState.drum) { const k = Math.abs(Math.sin(t * 7)); c.save(); c.globalAlpha = 0.9; c.strokeStyle = '#ffe9a8'; c.lineWidth = 2; for (let i = 0; i < 2; i++) { c.beginPath(); c.arc(u.x, u.y - size * 0.55, 8 + i * 6 + k * 4, -Math.PI * 0.85, -Math.PI * 0.15); c.stroke(); } c.restore(); }
