    c.save(); c.globalAlpha = 0.22; c.fillStyle = '#fff8dc';
    for (let i = 0; i < 14; i++) { const a = (i / 14) * TAU + t * 0.12; c.beginPath(); c.moveTo(W2 / 2, 330); c.lineTo(W2 / 2 + Math.cos(a - 0.07) * 700, 330 + Math.sin(a - 0.07) * 700); c.lineTo(W2 / 2 + Math.cos(a + 0.07) * 700, 330 + Math.sin(a + 0.07) * 700); c.closePath(); c.fill(); }
