    const rk = easeOutBack(clamp(t / 0.45));
    c.save(); c.translate(W2 / 2, 92); c.scale(rk, rk); UI.ribbon(c, 0, 0, 300, 54, 'CAMPAIGN COMPLETE', PAL.gold, { size: 21, fill: '#fffaf0', letter: 1 }); c.restore();
    const mk = easeOutBack(clamp((t - 0.3) / 0.6));
