    text(c, { gold: 'Gold', silver: 'Silver', bronze: 'Bronze' }[tier] + ' · ' + C.title, W2 / 2, 502, { size: 14, weight: 700, fill: '#fff6e0', stroke: INK, strokeW: 3.5, maxW: W2 - 40 });
