/* Roll to War: title screen, level select, settings */

function settingsOverlay(scene, c) {
  const A = GAME.app, W2 = A.W;
  if (!scene.settingsOpen) return;
  c.save(); c.fillStyle = 'rgba(12,8,4,0.72)'; c.fillRect(0, 0, W2, A.H);
  A.hit('settingsBg', 0, 0, W2, A.H, () => { scene.settingsOpen = false; });
  UI.panel(c, 40, 226, W2 - 80, 366, 18, { seed: 6 });
  A.hit('settingsPanel', 40, 226, W2 - 80, 366, () => {});
  RTW.text(c, 'SETTINGS', W2 / 2, 264, { size: 24, font: F.head, weight: 900, grad: ['#fff6cf', '#ffd76a', '#d7901f'], stroke: INK, strokeW: 5, letter: 3 });
  const row = (id, y, label, on, fn) => {
    const p = A.hit(id, 70, y, W2 - 140, 46, fn);
    UI.button(c, 70, y + (p ? 2 : 0), W2 - 140, 46, label + (on ? '  ON' : '  OFF'), on ? 'green' : 'wood', { size: 16 });
  };
  row('sfxT', 292, 'SOUND', GAME.settings.sound, () => { GAME.settings.sound = !GAME.settings.sound; GAME.saveSettings(); GAME.sfx.apply(); GAME.sfx.tap(); });
  row('musT', 346, 'MUSIC', GAME.settings.music, () => { GAME.settings.music = !GAME.settings.music; GAME.saveSettings(); GAME.sfx.apply(); GAME.sfx.tap(); });
  row('voxT', 400, 'VOICE', GAME.settings.voice !== false, () => { GAME.settings.voice = GAME.settings.voice === false; GAME.saveSettings(); if (!GAME.settings.voice) GAME.voice.stop(); GAME.sfx.tap(); });
  const pr = A.hit('resetP', 70, 456, W2 - 140, 42, () => {
    if (scene.confirmReset) {
      // a fresh save, stamped so the cloud copy does not bring the old progress back (test mode also forgets its clan)
      GAME.progress = GAME.eco ? GAME.eco.ensure({ unlocked: 1, best: {}, stars: {}, played: {}, camp: {}, resetAt: Date.now() }) : { unlocked: 1, best: {}, stars: {}, played: {}, camp: {} };
      if (GAME.online && GAME.online.be && GAME.online.mode === 'test') { GAME.online.be.net = {}; GAME.online.be.saveNet(); }
      GAME.saveProgress(); if (GAME.eco) GAME.eco.applyEquip(); if (GAME.online) GAME.online.log('progress_reset', {});
      scene.confirmReset = false; GAME.sfx.tap();
    }
    else { scene.confirmReset = true; GAME.sfx.select(); }
  });
  UI.button(c, 70, 456 + (pr ? 2 : 0), W2 - 140, 42, scene.confirmReset ? 'TAP AGAIN TO RESET' : 'RESET PROGRESS', 'red', { size: 14 });
  const pc = A.hit('closeS', 70, 516, W2 - 140, 46, () => { scene.settingsOpen = false; scene.confirmReset = false; GAME.sfx.tap(); });
  UI.button(c, 70, 516 + (pc ? 2 : 0), W2 - 140, 46, 'CLOSE', 'gold', { size: 17 });
  c.restore();
}
function gearButton(scene, c, x, y) {
  const A = GAME.app;
  const p = A.hitCircle('gear', x, y, 22, () => { scene.settingsOpen = true; GAME.sfx.tap(); }, { onLong: () => { GAME.sfx.select(); GAME.tuning.open(); } });
  UI.roundBtn(c, x, y + (p ? 2 : 0), 20, 'gear');
}

