/* ===== src/game/80-tuning.js ===== */
/* Roll to War: hidden tuning panel (long-press the gear, or press T) */
GAME.tuning = {
  el: null,
  build() {
    const el = document.getElementById('tune');
    this.el = el;
    let html = '<div class="tp-head"><strong>Tuning panel</strong><span>Changes apply live; routing changes apply on restart.</span><button type="button" data-act="close" aria-label="Close tuning panel">✕</button></div><div class="tp-body">';
    for (const [sec, rows] of GAME.TUNE_SPEC) {
      html += `<fieldset><legend>${sec}</legend>`;
      for (const [key, label, min, max, step] of rows) {
        html += `<label class="tp-row"><span>${label}</span><input type="range" min="${min}" max="${max}" step="${step}" data-k="${key}"><output data-o="${key}"></output></label>`;
      }
      html += '</fieldset>';
    }
    html += '<fieldset><legend>Debug</legend>' +
      '<label class="tp-chk"><input type="checkbox" data-dev="routes"> Show planned routes</label>' +
      '<label class="tp-chk"><input type="checkbox" data-dev="fps"> Show FPS</label>' +
      '<label class="tp-chk"><input type="checkbox" data-dev="unlockAll"> Unlock all levels</label></fieldset>';
    html += '</div><div class="tp-foot"><button type="button" data-act="restart">Restart level</button><button type="button" data-act="reset">Reset defaults</button><button type="button" data-act="close">Close</button></div>';
    el.innerHTML = html;
    el.addEventListener('input', (e) => {
      const k = e.target.getAttribute('data-k');
      if (k) { GAME.CFG[k] = +e.target.value; this.sync(); this.save(); }
      const d = e.target.getAttribute('data-dev');
      if (d) { GAME.dev[d] = e.target.checked; GAME.Store.set('dev', GAME.dev); }
    });
    el.addEventListener('click', (e) => {
      const a = e.target.getAttribute('data-act');
      if (a === 'close') this.close();
      else if (a === 'reset') { Object.assign(GAME.CFG, GAME.DEFAULTS); this.save(); this.sync(); }
      else if (a === 'restart') { GAME.mazeCache = {}; const s = GAME.app.scene; if (s && s.ctx) GAME.app.setScene(s.ctx.restart()); else if (s && s.li != null) GAME.app.setScene(new GAME.RallyScene(s.li)); else if (s instanceof GAME.LevelsScene) GAME.app.setScene(new GAME.LevelsScene()); this.close(); }
    });
    ['pointerdown', 'pointerup', 'keydown'].forEach((ev) => el.addEventListener(ev, (e) => e.stopPropagation()));
  },
  save() { const diff = {}; for (const k in GAME.DEFAULTS) if (GAME.CFG[k] !== GAME.DEFAULTS[k]) diff[k] = GAME.CFG[k]; GAME.Store.set('tune', diff); },
  sync() {
    if (!this.el) return;
    this.el.querySelectorAll('input[data-k]').forEach((i) => { const k = i.getAttribute('data-k'); i.value = GAME.CFG[k]; });
    this.el.querySelectorAll('output[data-o]').forEach((o) => { const v = GAME.CFG[o.getAttribute('data-o')]; o.textContent = Math.round(v * 100) / 100; });
    this.el.querySelectorAll('input[data-dev]').forEach((i) => { i.checked = !!GAME.dev[i.getAttribute('data-dev')]; });
  },
  open() { if (!this.el) this.build(); this.sync(); this.el.hidden = false; const s = GAME.app.scene; if (s && s.phase === 'play') s.paused = true; },
  close() { if (this.el) this.el.hidden = true; },
  toggle() { if (this.el && !this.el.hidden) this.close(); else this.open(); },
};

