/* ===== btw-00-core.js ===== */
/* Bounce to War: core. A puzzle game in the Roll to War universe: place pink arrows to route each crew to its house
   through gates, camps and gear chests; the crews of a battle's three boards form the army that faces the enemy
   commander, and the gear they found becomes battle powers. Same troops, art, story and narration as Roll to War. */
const BTW = (GAME.btw = { start: {} });
const DK = ['up', 'right', 'down', 'left'];
const DV = { up: [-1, 0], right: [0, 1], down: [1, 0], left: [0, -1] };
BTW.DK = DK; BTW.DV = DV;
BTW.turnR = (d) => DK[(DK.indexOf(d) + 1) % 4];
BTW.turnL = (d) => DK[(DK.indexOf(d) + 3) % 4];
BTW.ang = (d) => ({ right: 0, down: Math.PI / 2, left: Math.PI, up: -Math.PI / 2 })[d] || 0;
const SW2 = 390, SH2 = 844;

/* ---------- saved progress (its own keys: Roll to War's save is not touched) ---------- */
BTW.Store = {
  get(k, def) { try { const v = window.localStorage.getItem('btw.' + k); return v == null ? def : JSON.parse(v); } catch (e) { return def; } },
  set(k, v) { try { window.localStorage.setItem('btw.' + k, JSON.stringify(v)); } catch (e) { /* storage unavailable: progress lasts this visit */ } },
};
BTW.fresh = () => ({ v: 1, intro: false, chapters: {}, boards: {}, battles: {}, last: null, done: false, tips: {} });
BTW.P = Object.assign(BTW.fresh(), BTW.Store.get('progress', {}));
BTW.save = () => BTW.Store.set('progress', BTW.P);
// a board's saved result: best army (soldiers per crew, with armor/attack), stars, and every gear chest ever opened
BTW.boardRec = (id) => BTW.P.boards[id] || null;

/* ---------- gear: chests on the boards, powers in the battle ---------- */
const GEAR = (BTW.GEAR = {
  C: { key: 'caltrops', name: 'Caltrops', short: 'CALTROPS', cd: 12, counter: 'charge', desc: 'Iron spikes in the sand: a charge that hits them breaks, and enemy riders slow down.' },
  N: { key: 'naft', name: 'Fire Pots', short: 'FIRE POTS', cd: 11, counter: 'cry', desc: 'Pots of burning naft thrown at the commander: they hurt him and break his rally.' },
  H: { key: 'shield', name: 'Shield Wall', short: 'SHIELD WALL', cd: 14, counter: 'storm', desc: 'Shields up for 4 seconds: arrows and stones do a third of the damage.' },
  D: { key: 'drums', name: 'War Drums', short: 'WAR DRUMS', cd: 15, counter: null, desc: 'The kettle drums roll: your riders charge again, faster and harder, for 5 seconds.' },
  B: { key: 'banner', name: "Sultan's Banner", short: 'BANNER', cd: 18, counter: null, desc: 'The yellow banner is raised: every soldier heals a third and fights harder for 6 seconds.' },
});
BTW.GEAR_ORDER = ['C', 'N', 'H', 'D', 'B'];
const GI = (BTW.GEAR_ICON = {
  C: (c, x, y, s) => {   // a caltrop: four iron spikes
    c.save(); c.translate(x, y); const k = s / 20;
    const spike = (a, len) => { c.save(); c.rotate(a); c.beginPath(); c.moveTo(-2.6 * k, 0); c.lineTo(0, -len * k); c.lineTo(2.6 * k, 0); c.closePath(); c.restore(); };
    c.lineJoin = 'round';
    for (const [a, len] of [[-0.1, 11], [2.1, 10], [4.2, 10], [3.14, 6]]) { spike(a, len); c.lineWidth = Math.max(1.5, 2.2 * k); c.strokeStyle = INK; c.stroke(); c.fillStyle = a === 3.14 ? PAL.steelD : PAL.steel; c.fill(); }
    c.beginPath(); circ(c, 0, 0, 3 * k); c.fillStyle = PAL.steelDD; c.fill(); c.lineWidth = 1.3 * k; c.strokeStyle = INK; c.stroke();
    c.fillStyle = 'rgba(255,255,255,0.7)'; c.beginPath(); circ(c, -0.8 * k, -4.5 * k, 1 * k); c.fill();
    c.restore();
  },
  N: (c, x, y, s) => {   // a clay pot of naft, burning
    c.save(); c.translate(x, y); const k = s / 20;
    c.beginPath(); c.moveTo(-4 * k, -4 * k); c.quadraticCurveTo(-10 * k, 0, -8 * k, 6 * k); c.quadraticCurveTo(0, 12 * k, 8 * k, 6 * k); c.quadraticCurveTo(10 * k, 0, 4 * k, -4 * k); c.closePath();
    c.lineWidth = Math.max(1.5, 2.2 * k); c.strokeStyle = INK; c.lineJoin = 'round'; c.stroke(); const g = c.createLinearGradient(0, -4 * k, 0, 10 * k); g.addColorStop(0, '#c9804a'); g.addColorStop(1, '#8a4f28'); c.fillStyle = g; c.fill();
    c.fillStyle = 'rgba(255,230,190,0.35)'; c.fillRect(-7 * k, 1 * k, 14 * k, 1.8 * k);
    c.beginPath(); rr(c, -4.5 * k, -6.5 * k, 9 * k, 3.4 * k, 1.5 * k); c.fillStyle = '#b36d3d'; c.fill(); c.lineWidth = 1.4 * k; c.stroke();
    c.beginPath(); c.moveTo(0, -18 * k); c.quadraticCurveTo(6 * k, -11 * k, 3 * k, -6 * k); c.quadraticCurveTo(0, -5 * k, -3 * k, -6 * k); c.quadraticCurveTo(-6 * k, -11 * k, 0, -18 * k); c.closePath();
    const fg = c.createLinearGradient(0, -18 * k, 0, -6 * k); fg.addColorStop(0, '#ffe07a'); fg.addColorStop(1, '#ff7a2e'); c.fillStyle = fg; c.fill(); c.lineWidth = 1.3 * k; c.stroke();
    c.restore();
  },
  H: (c, x, y, s) => {   // round Ayyubid shields, overlapping in a wall
    c.save(); c.translate(x, y); const k = s / 20;
    for (const [ox, oy, col] of [[-6, -2, '#2f8a4c'], [6, -2, '#b8312a'], [0, 3, '#e2b33a']]) {
      c.beginPath(); circ(c, ox * k, oy * k, 7.5 * k); c.lineWidth = Math.max(1.4, 2 * k); c.strokeStyle = INK; c.stroke(); c.fillStyle = col; c.fill();
      c.beginPath(); circ(c, ox * k, oy * k, 4.8 * k); c.lineWidth = 1.2 * k; c.strokeStyle = 'rgba(255,240,200,0.7)'; c.stroke();
      c.beginPath(); circ(c, ox * k, oy * k, 1.8 * k); c.fillStyle = PAL.steelL; c.fill(); c.lineWidth = 1 * k; c.strokeStyle = INK; c.stroke();
    }
    c.restore();
  },
  D: (c, x, y, s) => {   // a kettle drum with two sticks
    c.save(); c.translate(x, y); const k = s / 20;
    c.beginPath(); c.moveTo(-10 * k, -2 * k); c.quadraticCurveTo(-9 * k, 10 * k, 0, 10 * k); c.quadraticCurveTo(9 * k, 10 * k, 10 * k, -2 * k); c.closePath();
    c.lineWidth = Math.max(1.5, 2.2 * k); c.strokeStyle = INK; c.lineJoin = 'round'; c.stroke(); const g = c.createLinearGradient(0, -2 * k, 0, 10 * k); g.addColorStop(0, '#e2b33a'); g.addColorStop(1, '#a8741c'); c.fillStyle = g; c.fill();
    c.beginPath(); ell(c, 0, -2 * k, 10 * k, 3.4 * k); c.fillStyle = '#f4ead2'; c.fill(); c.lineWidth = 1.6 * k; c.stroke();
    c.lineCap = 'round';
    for (const sx of [-1, 1]) { c.beginPath(); c.moveTo(sx * 3 * k, -4 * k); c.lineTo(sx * 11 * k, -13 * k); c.lineWidth = 3 * k; c.strokeStyle = INK; c.stroke(); c.lineWidth = 1.4 * k; c.strokeStyle = PAL.woodL; c.stroke(); c.beginPath(); circ(c, sx * 11 * k, -13 * k, 2 * k); c.fillStyle = PAL.woodD; c.fill(); }
    c.restore();
  },
  B: (c, x, y, s) => {   // Saladin's yellow banner
    c.save(); c.translate(x, y); const k = s / 20;
    c.strokeStyle = INK; c.lineWidth = Math.max(2, 2.6 * k); c.beginPath(); c.moveTo(-7 * k, 11 * k); c.lineTo(-7 * k, -12 * k); c.stroke();
    c.strokeStyle = PAL.woodL; c.lineWidth = 1.2 * k; c.stroke();
    c.beginPath(); circ(c, -7 * k, -13 * k, 1.8 * k); c.fillStyle = PAL.gold; c.fill();
    c.beginPath(); c.moveTo(-6 * k, -10 * k); c.lineTo(10 * k, -10 * k); c.lineTo(10 * k, 5 * k); c.lineTo(2 * k, 1.5 * k); c.lineTo(-6 * k, 5 * k); c.closePath();
    c.lineWidth = Math.max(1.5, 2 * k); c.strokeStyle = INK; c.stroke(); c.fillStyle = '#f2c233'; c.fill();
    c.beginPath(); c.arc(2 * k, -3.5 * k, 3.2 * k, 0.6, 5.7); c.lineWidth = 1.4 * k; c.strokeStyle = '#8a5a12'; c.stroke();
    c.restore();
  },
});
// a gear chest on the board: closed with the gear floating above it, or opened
BTW.chest = function (c, x, y, s, g, open, t) {
  c.save();
  c.fillStyle = 'rgba(20,10,4,0.3)'; c.beginPath(); ell(c, x, y + s * 0.42, s * 0.46, s * 0.12); c.fill();
  const w = s * 0.78, h = s * 0.46, by = y + s * 0.4;
  c.beginPath(); rr(c, x - w / 2, by - h, w, h, 4); c.lineWidth = 2.4; c.strokeStyle = INK; c.stroke(); c.fillStyle = PAL.wood; c.fill();
  c.fillStyle = PAL.gold; c.fillRect(x - w / 2 + 2, by - h * 0.62, w - 4, 3.5); c.fillRect(x - 3, by - h * 0.8, 6, h * 0.5);
  if (open) { c.beginPath(); rr(c, x - w / 2, by - h - s * 0.22, w, s * 0.2, 3); c.lineWidth = 2.2; c.stroke(); c.fillStyle = PAL.woodD; c.fill(); }
  else {
    c.beginPath(); c.moveTo(x - w / 2, by - h); c.quadraticCurveTo(x, by - h - s * 0.3, x + w / 2, by - h); c.closePath(); c.lineWidth = 2.4; c.stroke(); c.fillStyle = PAL.woodL; c.fill();
    const bob = Math.sin(t * 3 + x) * 2.5, iy = by - h - s * 0.55 + bob;
    c.save(); c.globalCompositeOperation = 'lighter'; c.globalAlpha = 0.55; c.drawImage(AMB.glow('#ffe7a0'), x - s * 0.45, iy - s * 0.45, s * 0.9, s * 0.9); c.restore();
    GI[g](c, x, iy, s * 0.46);
  }
  c.restore();
};

/* ---------- the pink arrow: the player's piece ---------- */
function arrowPath(c, s) {
  c.beginPath();
  c.moveTo(-s * 0.72, -s * 0.2); c.lineTo(s * 0.05, -s * 0.2); c.lineTo(s * 0.05, -s * 0.52); c.lineTo(s * 0.78, 0);
  c.lineTo(s * 0.05, s * 0.52); c.lineTo(s * 0.05, s * 0.2); c.lineTo(-s * 0.72, s * 0.2); c.closePath();
}
BTW.arrow = function (c, x, y, s, a, o = {}) {
  c.save(); c.translate(x, y); c.rotate(a);
  c.save(); c.translate(s * 0.06, s * 0.1); arrowPath(c, s); c.fillStyle = 'rgba(70,15,40,0.35)'; c.fill(); c.restore();
  arrowPath(c, s); c.lineJoin = 'round'; c.lineWidth = Math.max(1.6, s * 0.1); c.strokeStyle = INK; c.stroke();
  const base = o.stone ? '#c98aa5' : PAL.pink, hi = o.stone ? '#e8bfd0' : PAL.pinkL;
  const g = c.createLinearGradient(0, -s * 0.52, 0, s * 0.52); g.addColorStop(0, hi); g.addColorStop(0.55, base); g.addColorStop(1, shade(base, -0.14));
  c.fillStyle = g; c.fill();
  c.strokeStyle = 'rgba(255,255,255,0.7)'; c.lineWidth = Math.max(0.8, s * 0.045); c.lineCap = 'round';
  c.beginPath(); c.moveTo(-s * 0.6, -s * 0.1); c.lineTo(s * 0.02, -s * 0.1); c.stroke();
  c.restore();
};
// a movable arrow tile (the pink-rimmed plate); o.mult = the ×2 arrow, o.ghost = a hint, o.lift = being dragged
BTW.arrowTile = function (c, x, y, T, a, t, o = {}) {
  const s = T * 0.86, ly = o.lift ? 4 : 0;
  c.save();
  if (o.ghost) c.globalAlpha = 0.55 + 0.2 * Math.sin(t * 6);
  if (o.lift) { c.fillStyle = 'rgba(20,10,4,0.3)'; c.beginPath(); rr(c, x - s / 2 + 3, y - s / 2 + 7, s, s, 9); c.fill(); }
  c.beginPath(); rr(c, x - s / 2, y - s / 2 - ly, s, s, 9); c.lineWidth = 2.6; c.strokeStyle = o.ghost ? '#ffffff' : INK; c.stroke();
  const g = c.createLinearGradient(0, y - s / 2, 0, y + s / 2); g.addColorStop(0, o.mult ? '#fff1c4' : '#fbe3ec'); g.addColorStop(1, o.mult ? '#e9c46a' : '#e7b7cb'); c.fillStyle = g; c.fill();
  if (o.sel) { c.globalAlpha = 0.6 + 0.4 * Math.sin(t * 8); c.lineWidth = 3; c.strokeStyle = '#ffffff'; c.beginPath(); rr(c, x - s / 2 - 3.5, y - s / 2 - 3.5 - ly, s + 7, s + 7, 11); c.stroke(); c.globalAlpha = 1; }
  BTW.arrow(c, x, y - ly, s * 0.62, a);
  if (o.mult) {
    const bx = x + s / 2 - 6, by = y - s / 2 + 6 - ly;
    c.beginPath(); circ(c, bx, by, 9); c.lineWidth = 2; c.strokeStyle = INK; c.stroke(); c.fillStyle = PAL.gate2; c.fill();
    text(c, '×' + o.mult, bx, by + 0.5, { size: 9.5, weight: 700, fill: '#fff', stroke: INK, strokeW: 2 });
  }
  c.restore();
};
// a fixed arrow: set in the paving, it cannot be moved
BTW.fixedArrow = function (c, x, y, T, a) {
  c.save();
  c.beginPath(); rr(c, x - T * 0.4, y - T * 0.4, T * 0.8, T * 0.8, 7); c.fillStyle = 'rgba(90,60,40,0.28)'; c.fill();
  c.lineWidth = 1.6; c.strokeStyle = 'rgba(60,35,20,0.55)'; c.stroke();
  for (const [sx, sy] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]) { c.beginPath(); circ(c, x + sx * T * 0.3, y + sy * T * 0.3, 1.8); c.fillStyle = PAL.steelD; c.fill(); }
  BTW.arrow(c, x, y, T * 0.5, a, { stone: true });
  c.restore();
};

/* ---------- speech bubble and the ghost hand (tutorials) ---------- */
BTW.bubble = function (c, x, y, str, tail = true, o = {}) {
  c.save();
  const size = o.size || 13, w = Math.min(SW2 - 12, textWidth(c, str, size, F.body, 700) + 24), bx = clamp(x - w / 2, 6, SW2 - w - 6), by = y - 40;
  c.beginPath(); rr(c, bx, by, w, 27, 13.5); c.fillStyle = o.fill || '#fffaf0'; c.fill(); c.lineWidth = 2.5; c.strokeStyle = INK; c.stroke();
  text(c, str, bx + w / 2, by + 14, { size, weight: 700, fill: o.col || INK, maxW: w - 14 });
  if (tail) { const tx = clamp(x, bx + 14, bx + w - 14); c.beginPath(); c.moveTo(tx - 9, y - 13); c.lineTo(tx + 9, y - 13); c.lineTo(tx, y); c.closePath(); c.fillStyle = o.fill || '#fffaf0'; c.fill(); c.stroke(); c.fillRect(tx - 8, y - 15.5, 16, 3.5); }
  c.restore();
};
function ghostHand(c, x, y, s, a, press) {
  c.save(); c.translate(x, y); c.scale(s, s); c.rotate(-0.38); c.globalAlpha *= a;
  const sil = () => {
    c.beginPath();
    rr(c, -6.4, -1.5, 12.8, 34, 6.4); rr(c, -4, 22, 29, 30, 10); rr(c, 4.5, 19.5, 10.5, 16, 5.2); rr(c, 12.5, 22.5, 10, 15, 5); rr(c, 19.5, 27, 9, 13, 4.5);
    c.moveTo(-3, 30); c.quadraticCurveTo(-15, 26, -16.5, 34); c.quadraticCurveTo(-16, 41, -4, 44); c.closePath();
    rr(c, -3.5, 47, 28, 12, 3);
  };
  c.save(); c.translate(3, 5); sil(); c.fillStyle = 'rgba(10,6,3,0.28)'; c.fill(); c.restore();
  sil(); c.lineWidth = 5; c.lineJoin = 'round'; c.strokeStyle = INK; c.stroke();
  sil(); c.fillStyle = '#fffaf2'; c.fill();
  c.save(); sil(); c.clip(); c.fillStyle = 'rgba(190,160,120,0.28)'; c.beginPath(); rr(c, 14, 22, 16, 32, 6); c.fill(); c.restore();
  c.strokeStyle = 'rgba(35,23,15,0.55)'; c.lineWidth = 1.3; c.lineCap = 'round';
  c.beginPath(); c.moveTo(-2.5, 3); c.quadraticCurveTo(0, 0.5, 2.5, 3); c.stroke();
  for (const [x0, y0, x1] of [[5.5, 35, 13], [13.5, 37, 20.5], [20, 39.5, 26]]) { c.beginPath(); c.moveTo(x0, y0); c.quadraticCurveTo((x0 + x1) / 2, y0 + 2, x1, y0 - 0.5); c.stroke(); }
  c.beginPath(); rr(c, -5, 51, 32, 11, 3.5); c.lineWidth = 3; c.strokeStyle = INK; c.stroke();
  const cg = c.createLinearGradient(0, 51, 0, 62); cg.addColorStop(0, TEAMS.blue.light); cg.addColorStop(1, TEAMS.blue.dark); c.fillStyle = cg; c.fill();
  c.fillStyle = PAL.goldL; c.fillRect(-4, 52.2, 30, 2);
  c.restore();
  if (press > 0) { c.save(); c.globalAlpha = a * press * 0.9; c.fillStyle = '#fff3c4'; c.beginPath(); circ(c, x, y, 5 * s); c.fill(); c.restore(); }
}
class Ghost {
  constructor() { this.x = SW2 + 40; this.y = SH2 + 40; this.vis = 0; this.show = false; this.mv = null; this.press = 0; this.rip = []; this.hover = 0; this.carry = null; }
  go(x, y, dur = 0.6) { this.mv = { x0: this.x, y0: this.y, x1: x, y1: y, t: 0, dur }; this.show = true; }
  put(x, y) { this.x = x; this.y = y; this.mv = null; this.show = true; }
  tap() { this.press = 1e-3; this.rip.push({ x: this.x, y: this.y, t: 0 }); }
  hide() { this.show = false; }
  update(dt) {
    this.vis = clamp(this.vis + (this.show ? dt * 5 : -dt * 4));
    const m = this.mv;
    if (m) {
      m.t += dt; const k = smooth(m.t / m.dur), arc = this.carry ? 0 : Math.min(1, Math.hypot(m.x1 - m.x0, m.y1 - m.y0) / 140);
      this.x = lerp(m.x0, m.x1, k); this.y = lerp(m.y0, m.y1, k) - Math.sin(Math.PI * k) * 18 * arc;
      if (m.t >= m.dur) this.mv = null;
    }
    if (this.press > 0) { this.press += dt; if (this.press > 0.34) this.press = 0; }
    for (const r of this.rip) r.t += dt;
    this.rip = this.rip.filter((r) => r.t < 0.65);
    this.hover += dt;
  }
  draw(c, s = 1) {
    if (this.vis <= 0.01) return;
    for (const r of this.rip) {
      const k = r.t / 0.65;
      c.save(); c.globalAlpha = (1 - k) * this.vis; c.lineWidth = 3 * s * (1 - k * 0.5); c.strokeStyle = '#fff3c4';
      c.beginPath(); circ(c, r.x, r.y, (6 + 22 * easeOut(k)) * s); c.stroke(); c.restore();
    }
    const p = this.press > 0 ? Math.sin(Math.PI * clamp(this.press / 0.34)) : 0, bob = this.mv || p || this.carry ? 0 : Math.sin(this.hover * 4) * 2.2 * s;
    ghostHand(c, this.x, this.y + bob + p * 3 * s, s * (1 - 0.1 * p), this.vis, p);
  }
}
BTW.Ghost = Ghost; BTW.hand = ghostHand;

/* ---------- word wrap and a few shared bits ---------- */
BTW.wrap = function (c, str, maxW, size, weight = 600, font = F.body) {
  const out = [];
  for (const para of String(str).split('\n')) {
    const words = para.split(' '); let line = '';
    for (const w of words) { const test = line ? line + ' ' + w : w; if (textWidth(c, test, size, font, weight) > maxW && line) { out.push(line); line = w; } else line = test; }
    out.push(line);
  }
  return out;
};
BTW.stars = function (c, x, y, n, of, r, gap) { for (let k = 0; k < of; k++) ICON.star(c, x - ((of - 1) * gap) / 2 + k * gap, y, r, k < n); };
BTW.btn = function (c, id, x, y, w, h, label, style, fn, o = {}) {
  const A = GAME.app, p = A.hit(id, x, y, w, h, () => { if (o.disabled) { GAME.sfx.deny(); return; } GAME.sfx.tap(); fn(); }, { btn: true });
  c.save(); if (o.disabled) c.globalAlpha = 0.5;
  UI.button(c, x, y + (p && !o.disabled ? 2 : 0), w, h, label, style, { size: o.size || 16, letter: o.letter });
  c.restore();
  return p;
};
BTW.roman = ['I', 'II', 'III', 'IV', 'V'];

/* ===== btw-10-board.js ===== */
/* Bounce to War: the board. A crew marches straight until a pink arrow turns it, and must leave through its own
   house's door on the top edge. Tiles:
     '.' road (arrows go here)   '#' rock   'T' palm or olive tree   ',' sand   'o' water
     '2' '3' gates: multiply the crew (once each)        '+' camp: adds soldiers (board.plus, once each)
     'X' spikes or burning grass: halve the crew (once)  'A' shields / 'F' fists: the whole crew carries armor / attack
     'C' 'N' 'H' 'D' 'B' gear chests (each opened once, by the first crew that passes)
     'L' the sappers' mine: the first crew over it brings down every 'G' wall tile (they become road)
   Crews enter from a pad under the board (pad = column) or from the left or right edge (side 'L' | 'R', row).
   Fixed arrows (board.fixed) are set in the paving and turn every crew. */
const GEARCH = 'CNHDB';
BTW.cell = (B, r, c) => (r < 0 || c < 0 || r >= B.rows || c >= B.cols ? null : B.grid[r][c]);
BTW.walk = (ch, open) => ch != null && !'#T,o'.includes(ch) && (ch !== 'G' || open);
BTW.free = (B, r, c) => BTW.cell(B, r, c) === '.' && !(B.fixed || []).some(([fr, fc]) => fr === r && fc === c);   // where an arrow may go
BTW.start = (B, crew) => (crew.side === 'L' ? { r: crew.row, c: -1, d: 'right' } : crew.side === 'R' ? { r: crew.row, c: B.cols, d: 'left' } : { r: B.rows, c: crew.pad, d: 'up' });
BTW.fixedMap = (B) => { const m = new Map(); (B.fixed || []).forEach(([r, c, d], i) => m.set(r * B.cols + c, { dir: d, mult: 1, id: 'f' + i, fixed: true })); return m; };

// Trace one crew. arrows: Map key r*cols+c -> { dir, mult, id } (fixed arrows are added here). st: { taken: Set of
// gear cell keys already opened, open: the wall is down }.
BTW.trace = function (B, crew, arrows, st = {}) {
  const taken = st.taken || new Set(), out = { pts: [], ev: [], n: crew.n, n0: crew.n, armor: false, attack: false, gear: [], end: 'stuck', turns: 0, opens: false, stuckAt: null };
  const s0 = BTW.start(B, crew), cols = B.cols, fixed = BTW.fixedMap(B);
  let r = s0.r, c = s0.c, d = s0.d, n = crew.n, open = !!st.open;
  const seen = new Set(), usedG = new Set(), usedX = new Set(), usedP = new Set(), usedA = new Set();
  out.pts.push([r, c]);
  for (let guard = 0; guard < 400; guard++) {
    const nr = r + DV[d][0], nc = c + DV[d][1];
    if (nr < 0) {
      const door = Object.keys(B.doors).find((k) => B.doors[k] === nc);
      out.pts.push([nr, nc]);
      out.end = !door ? 'wall' : door === crew.type ? 'home' : 'wrong'; out.door = door || null;
      break;
    }
    const ch = BTW.cell(B, nr, nc);
    if (!BTW.walk(ch, open)) { out.end = nr >= B.rows || nc < 0 || nc >= cols ? 'back' : ch === 'G' ? 'gate' : 'stuck'; out.stuckAt = [nr, nc]; break; }
    r = nr; c = nc;
    const key = r * cols + c, k2 = key * 4 + DK.indexOf(d);
    if (seen.has(k2)) { out.end = 'loop'; break; }
    seen.add(k2);
    out.pts.push([r, c]);
    const at = out.pts.length - 1;
    if (ch === '2' || ch === '3') { if (!usedG.has(key)) { usedG.add(key); const m = +ch; n *= m; out.ev.push({ at, kind: 'gate', m, n }); } }
    else if (ch === 'X') { if (!usedX.has(key)) { usedX.add(key); n = Math.ceil(n / 2); out.ev.push({ at, kind: 'hazard', n }); } }
    else if (ch === '+') { if (!usedP.has(key)) { usedP.add(key); n += B.plus || 2; out.ev.push({ at, kind: 'camp', add: B.plus || 2, n }); } }
    else if (ch === 'A') { if (!out.armor) { out.armor = true; out.ev.push({ at, kind: 'armor' }); } }
    else if (ch === 'F') { if (!out.attack) { out.attack = true; out.ev.push({ at, kind: 'attack' }); } }
    else if (ch === 'L') { if (!open) { open = true; out.opens = true; out.ev.push({ at, kind: 'mine' }); } }
    else if (GEARCH.includes(ch) && !taken.has(key) && !out.gear.includes(ch)) { out.gear.push(ch); out.ev.push({ at, kind: 'gear', g: ch, key }); }
    const ar = arrows.get(key) || fixed.get(key);
    if (ar) {
      if (ar.dir !== d) out.turns++;
      d = ar.dir;
      if (ar.mult > 1 && !usedA.has(ar.id)) { usedA.add(ar.id); n *= ar.mult; out.ev.push({ at, kind: 'arrow', m: ar.mult, n }); }
    }
  }
  out.n = n;
  return out;
};
BTW.endMsg = (tr) => ({ home: '', wrong: "That's another crew's house", wall: 'They walk into the house wall', stuck: 'They hit a wall: add an arrow to turn them', gate: 'The city wall is still standing', loop: 'They would march in circles', back: 'They march back out' })[tr.end] || '';

/* ---------- the solver (tools, and the hints stored with each board) ----------
   Every route a crew can take with the board's arrow pool: a depth-first walk that may drop an arrow (any direction)
   on each free road tile it enters. Each crew is independent (arrows can be moved between crews); the wall ('G')
   couples them: solve each crew with the wall up and down, then pick the best order-respecting combination. */
BTW.solveCrew = function (B, crew, open) {
  const pool = B.arrows || [], plain = pool.filter((m) => m === 1).length, dbl = pool.filter((m) => m > 1).length;
  const fixed = BTW.fixedMap(B), cols = B.cols, res = [], arrows = new Map(), visited = new Set();
  const s0 = BTW.start(B, crew);
  const done = () => { const tr = BTW.trace(B, crew, arrows, { open }); if (tr.end === 'home') res.push({ n: tr.n, gear: tr.gear.slice(), armor: tr.armor, attack: tr.attack, opens: tr.opens, used: arrows.size, arr: [...arrows.entries()].map(([k, a]) => [Math.floor(k / cols), k % cols, a.dir, a.mult]) }); };
  let nodes = 0;
  function rec(r, c, d, pl, db, isOpen) {
    if (++nodes > 400000) return;
    const nr = r + DV[d][0], nc = c + DV[d][1];
    if (nr < 0) { done(); return; }
    const ch = BTW.cell(B, nr, nc);
    if (!BTW.walk(ch, isOpen)) return;
    const key = nr * cols + nc, sk = key * 4 + DK.indexOf(d);
    if (visited.has(sk)) return;
    const o2 = isOpen || ch === 'L';
    const f = fixed.get(key);
    if (f) { visited.add(sk); rec(nr, nc, f.dir, pl, db, o2); visited.delete(sk); return; }
    const a = arrows.get(key);
    if (a) { visited.add(sk); rec(nr, nc, a.dir, pl, db, o2); visited.delete(sk); return; }
    const cellSeen = [0, 1, 2, 3].some((k) => visited.has(key * 4 + k));
    visited.add(sk);
    rec(nr, nc, d, pl, db, o2);
    if (ch === '.' && !cellSeen) {
      for (const nd of DK) {
        if (pl > 0 && nd !== d) { arrows.set(key, { dir: nd, mult: 1, id: key }); rec(nr, nc, nd, pl - 1, db, o2); arrows.delete(key); }
        if (db > 0) { arrows.set(key, { dir: nd, mult: 2, id: key }); rec(nr, nc, nd, pl, db - 1, o2); arrows.delete(key); }
      }
    }
    visited.delete(sk);
  }
  rec(s0.r, s0.c, s0.d, plain, dbl, !!open);
  // keep the distinct useful routes: for each (n, gear, opens) the one with the fewest arrows
  const best = new Map();
  for (const x of res) { const k = x.n + '|' + x.gear.join('') + '|' + (x.opens ? 1 : 0) + '|' + (x.armor ? 1 : 0) + (x.attack ? 1 : 0); if (!best.has(k) || best.get(k).used > x.used) best.set(k, x); }
  return [...best.values()].sort((a, b) => b.n - a.n || a.used - b.used);
};
// the whole board: the best total with the crews in order (par), and the best total that also opens every gear
// chest (parAll: the three-star target); each crew's route in that plan becomes its hint
BTW.solveBoard = function (B) {
  const hasWall = B.grid.some((row) => row.includes('G'));
  const routes = B.crews.map((cr) => ({ closed: BTW.solveCrew(B, cr, false), open: hasWall ? BTW.solveCrew(B, cr, true) : null }));
  const chests = []; B.grid.forEach((row) => [...row].forEach((ch) => { if (GEARCH.includes(ch) && !chests.includes(ch)) chests.push(ch); }));
  const bit = (g) => 1 << chests.indexOf(g), full = (1 << chests.length) - 1;
  const memo = new Map();
  // best(i, open, mask): the most soldiers crews i.. can bring home, and whether every chest ends up opened
  const best = (i, open, mask, needAll) => {
    if (i >= B.crews.length) return needAll && mask !== full ? { n: -1e9, plan: [] } : { n: 0, plan: [] };
    const k = i + '|' + open + '|' + mask + '|' + needAll; if (memo.has(k)) return memo.get(k);
    const list = (open ? routes[i].open : routes[i].closed) || routes[i].closed;
    let bb = { n: -1e9, plan: [] };
    for (const r of list.slice(0, 80)) {
      let m2 = mask; for (const g of r.gear) m2 |= bit(g);
      const rest = best(i + 1, open || r.opens, m2, needAll);
      if (rest.n > -1e8 && r.n + rest.n > bb.n) bb = { n: r.n + rest.n, plan: [{ i, open, route: r }].concat(rest.plan) };
    }
    memo.set(k, bb); return bb;
  };
  const top = best(0, false, 0, false), all = chests.length ? best(0, false, 0, true) : top;
  const reach = {}; for (const g of chests) reach[g] = routes.some((R) => R.closed.some((x) => x.gear.includes(g)) || (R.open && R.open.some((x) => x.gear.includes(g))));
  const simple = routes.map((R) => { const al = R.closed.concat(R.open || []); if (!al.length) return null; const m = Math.min(...al.map((x) => x.used)); return al.filter((x) => x.used === m).sort((a, b) => b.n - a.n)[0]; });
  const plan = all.n > -1e8 ? all.plan : top.plan;
  return { par: top.n, parAll: all.n > -1e8 ? all.n : null, plan, routes, reach, simple, chests, ok: top.n > 0 };
};
// hint for crew i in the current wall state: the solver's plan when it matches, otherwise that crew's best route
BTW.hintFor = function (B, i, open) {
  const H = B.hints && B.hints[i]; if (!H) return null;
  return (open && H.open) || H.closed || null;
};
// ★ every crew home · ★★ at least 60% of the best total · ★★★ at least 90% of the best total that opens every chest,
// with every chest opened
BTW.starsFor = (B, total, gearAll) => {
  const t3 = Math.ceil((B.parAll || B.par) * 0.9);
  return total >= t3 && (gearAll || !B.chests || !B.chests.length) ? 3 : total >= Math.ceil(B.par * 0.6) ? 2 : 1;
};

