    this.ci = 0; this.M = null; this.results = []; this.plans = []; this.planned = new Set(); this.got = new Set();
    this.open = false; this.willOpen = false; this.breachT = null;
    this.starsGot = 0; this.starsFly = 0; this.gear = []; this.lock = new Set();
    this.turnStart = this.layout(); this.turnMoves = 0; this.hopT0 = -9;
