  startPlan() {
    if (this.learn) { BB.save('learn.' + this.L.learn, true); this.learn = false; }
    const back = this.introBack; this.introBack = null; this.phase = back || 'plan'; this.phaseT = 0; this.arrowT0 = this.t; GAME.sfx.tap();
  }
