    const S = (((this.L.sols || [])[op] || [])[ci] || []).map(([n, noR, gear, claims, lay, cells], i) => ({ i, n, noR, gear, claims: two(claims), lay: lay ? lay.split(',').map((q) => { const o = q.slice(-1), k = parseInt(q.slice(0, -1), 36); return [Math.floor(k / cols), k % cols, o]; }) : [], cells: new Set(two(cells)) }));
