        if (b.r === r && b.c === q) { BTW.bubble(c, clamp(this.cx(q), 120, 270), this.cy(r) - 28, say && /^Tap/.test(say) ? say : 'Now tap it to flip it', true); BTW.hand(c, this.cx(q) + 6, this.cy(r) + 8, 0.95, 1, (t % 1.2) < 0.25 ? 0.8 : 0); return; }
