      c.save(); c.beginPath(); rr(c, x, y, w, h, 10); c.clip(); c.fillStyle = col.main; c.fillRect(x, y, 6, h); c.restore();
      const art = artOf(crew.type), b = SPR.image('bncbust' + art + bs, bs, bs, (g) => { UI.bust(g, 0, 0, bs, bs, art, 'blue', 0, { r: 7 }); g.beginPath(); rr(g, 0, 0, bs, bs, 7); g.lineWidth = 2; g.strokeStyle = INK; g.stroke(); });
      c.drawImage(b.cv, x + 11, y + (h - bs) / 2 + (small ? 4 : 0), bs, bs);
