    text(c, 'RESET', W2 - 36, y2 + 50, { size: 8, font: F.head, weight: 900, fill: PAL.goldL, letter: 0.5 });
    const ready = this.ready, sb = A.hit('bnmarch', 70, BLx.SEND_Y - 10, W2 - 140, 54, () => this.march(), { btn: true });
    c.save(); if (!ready) c.globalAlpha = 0.5;
