    UI.button(c, 70, BLx.SEND_Y - 10 + (sb && ready ? 2 : 0), W2 - 140, 54, this.M ? 'MARCHING…' : 'MARCH!', ready ? 'gold' : 'wood', { size: this.M ? 18 : 22, letter: 3 });
    c.restore();
