          sp.holes = [{ x: 0, y: 0, w: W2, h: 140, rad: 0, plain: true }, { x: x - T / 2 - 22, y: y - T / 2 - 22, w: T + 44, h: T + 44 }, { x: 0, y: 626, w: W2, h: 218, rad: 0, plain: true }];
          SW.turnArrow(c, x, y, T * 0.66, t);
