          if (piv.o !== 'BR') { sp.point = [this.cx(piv.c) + 8, this.cy(piv.r) + 8]; SW.turnArrow(c, this.cx(piv.c), this.cy(piv.r), T * 0.66, t); }
          else if (!(free.r === tr && free.c === tc) && !this.drag) sp.drag = [this.cx(free.c), this.cy(free.r), this.cx(tc), this.cy(tr)];
