    SPR.blit(c, SPR.image('trtray', W2, H - y0 + 8, (g) => { g.fillStyle = 'rgba(0,0,0,0.3)'; g.fillRect(0, 0, W2, 8); UI.woodFill(g, 0, 8, W2, H - y0, 33, PAL.wood3); g.fillStyle = INK; g.fillRect(0, 8, W2, 3.5); g.fillStyle = PAL.gold; g.fillRect(0, 8.8, W2, 2); }), 0, y0 - 8);
