    c.fillStyle = 'rgba(10,6,3,0.4)'; c.beginPath(); rr(c, x + 2, y + 4, w, h, 12); c.fill();
    c.beginPath(); rr(c, x, y, w, h, 12); const g = c.createLinearGradient(0, y, 0, y + h); g.addColorStop(0, '#fff6e2'); g.addColorStop(1, '#e8d2a6'); c.fillStyle = g; c.fill(); c.lineWidth = 2.5; c.strokeStyle = INK; c.stroke();
