SAL.gatherTypical = function (T, boosts) { const g = SAL.gatherIdeal(T, boosts) * 0.8, B = SAL.GATHER.base, r5 = (v) => Math.round(v / 5) * 5; return { food: r5(B.food + g * 0.33), wood: r5(B.wood + g * 0.37), gold: r5(B.gold + g * 0.3) }; };
