    if (this.campDown(x, y)) return;
    if (this.arm === 'fast') { const k = this.siteAt(x, y); if (k) { this.fast[k] = this.el + SAL.GATHER.fastT; this.arm = null; this.say(SAL.SITES[k].x, SAL.SITES[k].y - SAL.SITES[k].r - 6, 'Faster work!', '#e9ffd8'); GAME.sfx.power(); return; } }
    const w = this.workerAt(x, y);
