  c.beginPath(); ell(c, 0, -12, 13, 6.5); c.fillStyle = '#8a5a34'; c.fill(); c.lineWidth = 2; c.stroke();
  c.beginPath(); ell(c, 14, -14, 5, 4.2); c.fillStyle = '#9a6a3c'; c.fill(); c.stroke();
  c.strokeStyle = '#efe4c6'; c.lineWidth = 1.6; c.beginPath(); c.moveTo(13, -17); c.quadraticCurveTo(11, -22, 15, -23); c.moveTo(16, -17); c.quadraticCurveTo(19, -21, 21, -20); c.stroke();
  c.restore();
