  c.strokeStyle = INK; c.lineWidth = 3.4; c.beginPath(); c.moveTo(x - 12, y); c.lineTo(x - 4, y - 34); c.moveTo(x + 4, y); c.lineTo(x - 4, y - 34); c.moveTo(x - 4, y - 34); c.lineTo(x + 22, y - 40); c.stroke();
