  c.beginPath(); rr(c, x - 20, y + 8, 40, 5, 2.5); c.fillStyle = 'rgba(15,8,3,0.6)'; c.fill(); c.beginPath(); rr(c, x - 20, y + 8, 40 * k, 5, 2.5); c.fillStyle = '#8fe0a6'; c.fill();
