  c.save(); c.fillStyle = 'rgba(40,25,10,0.07)'; for (const [ph, y, r] of [[0, 300, 90], [0.5, 520, 110]]) { const x = ((t * 7 + ph * 700) % 700) - 150; c.beginPath(); ell(c, x, y, r, r * 0.45); c.fill(); c.beginPath(); ell(c, x + r * 0.6, y + 8, r * 0.6, r * 0.3); c.fill(); } c.restore();
