/* ===== sal-41-field.js ===== */
/* The Saladin test campaign · the field battle (battle III, Hattin) and the troop muster before it. The battle is
   Roll to War's own: the armies fight on their own and a new offer of three bonus cards comes every 8 to 10
   seconds. The decision picks its twist: thirst (the Franks weaken every 10 seconds) or smoke (their crossbows
   shoot shorter and softer; the fires cost a fifth of the treasury). The enemy is sized from the best army the
   treasury could buy (SAL.bestMuster) times the chapter's share (bk). */
// musters: the treasury, the time, the cap, and the enemy's share of the best army that treasury buys
SAL.MUSTER = {
  hattin: { cash: { food: 500, wood: 250, gold: 600 }, time: 60, cap: 60, bk: 1.0, foe: 'King Guy', title: 'THE MUSTER · HATTIN', sub: 'Ashtara, June 1187' },
  jerusalem: { time: 45, cap: 50, bk: 1.25, foe: 'Balian', title: 'THE MUSTER · JERUSALEM', sub: 'The camp before the walls' },
  acre: { time: 45, cap: 60, bk: 0.95, foe: 'King Guy', title: 'THE MUSTER · ACRE', sub: 'The camp on the hills' },
  // harder: a smaller treasury against a stronger column, and less time
  arsuf: { cash: { food: 450, wood: 250, gold: 520 }, time: 45, cap: 55, bk: 0.9, foe: 'Richard', title: 'THE MUSTER · ARSUF', sub: 'The forest of Arsuf, September 1191' },
};
SAL.cashFor = function (ch, gathered) {
  const C = SAL.CH[ch], M = SAL.MUSTER[C.key], D = SAL.decision(ch), k = (D && D.cash) || 1, base = gathered || M.cash, out = {};
  for (const r of SAL.RES) out[r] = Math.round((base[r] || 0) * k / 5) * 5;
  return out;
};
// an enemy army of n soldiers in a mix
SAL.redArmy = function (mix, n) { const a = {}; for (const t of GAME.CREWS) a[t] = { n: Math.round(n * (mix[t] || 0)), armor: 0, attack: 0, both: 0 }; return a; };
// foot archers: the crossbow crew of the Sultan's army is horse archers; the first `foot` of them fight on foot
// (the longer range, slower, no riding away), drawn as Turkish archers
SAL.footArchers = function (sim) {
  const A = sim.armies.blue, k = (A && A.crossbow && A.crossbow.foot) || 0; if (!k) return;
  let n = 0, hp = sim.cfg.hpCrossbow;
  for (const u of sim.alive.blue) {
    if (u.type !== 'crossbow' || u.leader || n >= k) continue;
    n++; Object.assign(u, { art: 'turkArcher', skirmish: false, spd: 1, r: 5, hp: hp, maxHp: hp, dmgMul: 0.95, iv: GAME.UT.crossbow.interval * 0.8, strikeF: 0.3, rangeMul: 1.1, foot: true });
  }
};
// enemy commanders can be fought by anyone (not only by the one soldier paired with them), as in the commander
// battles: otherwise the last commander standing ties up one of your men in a long duel while the rest look on
SAL.openLeaders = function (sim) {
  for (const u of sim.leaders) if (u.commander) Object.defineProperty(u, 'partner', { get() { return null; }, set() {}, configurable: true });
};
SAL.prepSim = (sim) => { SAL.footArchers(sim); SAL.openLeaders(sim); };
GAME.TWISTS.salThirst = {
  title: 'Thirst', sub: 'The Franks weaken every 10 seconds', decor: 'hattin',
  setup(sim) { SAL.prepSim(sim); sim.twState.thirst = 0; },
  step(sim) { const S = sim.twState, k = Math.min(8, Math.floor(sim.t / 10)); while (S.thirst < k) { S.thirst++; sim.buff('red', null, { atk: 0.95, def: 1.02 }, Infinity); sim.events.push({ type: 'toast', str: 'Thirst: the Franks weaken', team: 'red' }); } },
  status(sim) { return { label: 'Thirst', col: '#9a5a1c', pips: [sim.twState.thirst || 0, 8] }; },
};
GAME.TWISTS.salSmoke = {
  title: 'Smoke', sub: 'The burning scrub spoils their crossbows', decor: 'hattin', smoke: true,
  setup(sim) { SAL.prepSim(sim); sim.buff('red', null, { atk: 0.94 }, Infinity); },
  range(sim, u) { return u.team === 'red' && u.type === 'crossbow' ? 0.6 : 1; },
  damage(sim, u, tg, dmg) { return u.team === 'red' && u.type === 'crossbow' ? dmg * 0.5 : dmg; },
};
GAME.TWISTS.salPlain = { title: 'The field', sub: 'No twist', setup(sim) { SAL.prepSim(sim); } };

