        S.volT += E.volley.every; S.volleyAt = sim.t; const on = this.onWall(sim);
        for (let i = 0; i < E.volley.n && on.length; i++) { const tg = on[(sim.rng() * on.length) | 0]; S.arrows = S.arrows || []; S.arrows.push({ x0: E.volley.x[i % E.volley.x.length] + (sim.rng() - 0.5) * 16, y0: E.volley.y - 14, tg, x1: tg.x, y1: tg.y - 6, t: 0, dur: 0.75 + sim.rng() * 0.2 }); }
