    c.beginPath(); rr(c, 14, 698, 190, 14, 7); c.fillStyle = 'rgba(15,8,3,0.65)'; c.fill();
    if (k > 0) { c.beginPath(); rr(c, 14, 698, Math.max(14, 190 * k), 14, 7); c.fillStyle = '#c2b596'; c.fill(); }
    text(c, S.breached ? 'Storm through the gap!' : Math.ceil(k * 100) + '%' + (S.sap ? (k < 0.3 ? ' · the sappers fire the props' : ' · the sappers dig') : '') + (S.fires && S.fires.length ? ' · fire!' : ''), 14, 722, { size: 10.5, weight: 700, fill: '#e9d6b0', align: 'left', maxW: 190 });
