      Object.assign(u, { wagon: true, wi: i, hp: R.wagonHp, maxHp: R.wagonHp, dmgMul: 0, rangedTaken: 0.3, r: 12, ctr: null });
      Object.defineProperty(u, 'partner', { get() { return null; }, set() {}, configurable: true });   // every raider can hack at it at once
      u.goto = { x, y, until: Infinity, loot: true }; sim.units.push(u); sim.alive.red.push(u); S.wagons.push(u);
